#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include "ossfuzz/fuzz_helpers.h"
#include "lib/lz4.h"
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int main(int argc,char**argv){FILE*f=fopen(argv[1],"rb"); fseek(f,0,SEEK_END); long n=ftell(f); rewind(f); uint8_t*buf=malloc(n); fread(buf,1,n,f); const uint8_t*data=buf; size_t sz=n; uint32_t seed=FUZZ_seed(&data,&sz); size_t bound=LZ4_compressBound(sz); uint32_t cap=FUZZ_rand32(&seed,0,bound); fprintf(stderr,"file=%ld payload=%zu bound=%zu cap=%u first=%02x%02x%02x%02x\n",n,sz,bound,cap,buf[0],buf[1],buf[2],buf[3]); char*dst=malloc(cap); int r=LZ4_compress_default((char*)data,dst,sz,cap); fprintf(stderr,"default r=%d\n",r); return 0;}
EOF
gcc -g -O1 -fsanitize=address -fno-omit-frame-pointer -I. /tmp/probe_file.c lib/lz4.c lib/xxhash.c -o /tmp/probe_file
python3 - <<'PY'
from pathlib import Path
Path('/workspace/poc1').write_bytes(bytes.fromhex('1d000000')+b'A'*1000)
PY
ASAN_OPTIONS=detect_leaks=0:halt_on_error=1 /tmp/probe_file /workspace/poc1 2>&1 | head -60

